/bin/bash -lc "cat > lib/books-store.js <<'EOF'
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, '..', 'data', 'books.json');

function normalizeBooks(books) {
  if ("'!Array.isArray(books)) {
    return [];
  }

  return books.map((book) => ({
    id: String(book.id ?? '"''),
    title: String(book.title ?? ''),
    author: String(book.author ?? ''),
    notes: String(book.notes ?? ''),
    status: book.status === 'finished' ? 'finished' : 'reading',
    createdAt: book.createdAt ?? new Date().toISOString(),
    finishedAt: book.finishedAt ?? null,
  }));
}

export async function listBooks() {
  try {
    const raw = await readFile(DATA_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    return normalizeBooks(parsed);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return [];
    }

    throw error;
  }
}

async function saveBooks(books) {
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2) + '\\n', 'utf8');
}

export async function addBook({ title, author, notes }) {
  const books = await listBooks();
  const trimmedTitle = title.trim();
  const trimmedAuthor = author.trim();
  const trimmedNotes = notes.trim();

  const idBase = "'`${trimmedTitle.toLowerCase()}-${Date.now()}`
    .replace(/[''^a-z0-9]+/g, '"'-')
    .replace(/"'^-+|-+$/g, '"'');

  const newBook = {
    id: idBase || "'`book-${Date.now()}`,
    title: trimmedTitle,
    author: trimmedAuthor,
    notes: trimmedNotes,
    status: '"'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };

  books.push(newBook);
  await saveBooks(books);

  return newBook;
}

export async function getBookById(id) {
  const books = await listBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function markFinished(id) {
  const books = await listBooks();
  const book = books.find((item) => item.id === id);

  if ("'!book) {
    return null;
  }

  if (book.status !== '"'finished') {
    book.status = 'finished';
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
  }

  return book;
}
EOF"

/bin/bash -lc "cat > server.js <<'EOF'
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { addBook, getBookById, listBooks, markFinished } from './lib/books-store.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT ?? 3000);

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('\"', '&quot;')
    .replaceAll(\"'\", '&#39;');
}

function formatDate(isoDate) {
  if ("'!isoDate) {
    return null;
  }

  return new Date(isoDate).toLocaleDateString('"'en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function getOrigin(request) {
  const protocolHeader = request.headers['x-forwarded-proto'];
  const protocol = Array.isArray(protocolHeader)
    ? protocolHeader[0]
    : protocolHeader?.split(',')[0]?.trim() || 'http';
  const host = request.headers.host ?? "'`localhost:${PORT}`;

  return `${protocol}://${host}`;
}

function renderLayout({ title, content }) {
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(title)}</title>
    <link rel="stylesheet" href="/styles.css" />
  </head>
  <body>
    <main class="container">
      ${content}
    </main>
  </body>
</html>`;
}

function renderBookItems(books, mode) {
  if (books.length === 0) {
    return '"'<p class=\"empty\">Nothing here yet.</p>';
  }

  return "'`<ul class="book-list">${books
    .map((book) => {
      const safeId = encodeURIComponent(book.id);
      const byline = `<p class="meta">${escapeHtml(book.author)}</p>`;
      const detailLink = `<a class="title-link" href="/books/${safeId}">${escapeHtml(book.title)}</a>`;

      if (mode === '"'reading') {
        return "'`<li class="book-item">
          <div>
            ${detailLink}
            ${byline}
          </div>
          <form method="post" action="/books/${safeId}/finish">
            <input type="hidden" name="returnTo" value="/" />
            <button type="submit">Mark finished</button>
          </form>
        </li>`;
      }

      return `<li class="book-item">
        <div>
          ${detailLink}
          ${byline}
        </div>
        <p class="status-note">Finished ${escapeHtml(formatDate(book.finishedAt) ?? '"'')}</p>
      </li>"'`;
    })
    .join('"'')}</ul>"'`;
}

function renderHome({ books, errorMessage = '"'', formValues = {} }) {
  const reading = books
    .filter((book) => book.status === 'reading')
    .sort((left, right) => new Date(right.createdAt) - new Date(left.createdAt));

  const finished = books
    .filter((book) => book.status === 'finished')
    .sort((left, right) => new Date(right.finishedAt || 0) - new Date(left.finishedAt || 0));

  return renderLayout({
    title: 'My Books',
    content: "'`
      <header class="header">
        <h1>My Reading Tracker</h1>
        <p>Track what you are reading and what you have finished.</p>
      </header>

      <section class="panel">
        <h2>Add a Book</h2>
        ${errorMessage ? `<p class="error">${escapeHtml(errorMessage)}</p>` : '"''}
        <form method=\"post\" action=\"/books\" class=\"form-grid\">
          <label>
            Title
            <input name=\"title\" required value=\""'${escapeHtml(formValues.title ?? '"'')}\" />
          </label>
          <label>
            Author
            <input name=\"author\" required value=\""'${escapeHtml(formValues.author ?? '"'')}\" />
          </label>
          <label>
            Notes
            <textarea name=\"notes\" rows=\"4\">"'${escapeHtml(formValues.notes ?? '"'')}</textarea>
          </label>
          <button type=\"submit\">Add Book</button>
        </form>
      </section>

      <section class=\"panel\">
        <h2>Currently Reading</h2>
        "'${renderBookItems(reading, '"'reading')}
      </section>

      <section class=\"panel\">
        <h2>Finished</h2>
        "'${renderBookItems(finished, '"'finished')}
      </section>
    "'`,
  });
}

function renderBookDetail({ book, origin }) {
  if (!book) {
    return renderLayout({
      title: '"'Book Not Found',
      content: "'`
        <section class="panel">
          <h1>Book Not Found</h1>
          <p>That book does not exist.</p>
          <p><a href="/">Back to all books</a></p>
        </section>
      `,
    });
  }

  const statusText = book.status === '"'finished' ? 'Finished' : 'Currently Reading';
  const shareUrl = "'`${origin}/books/${encodeURIComponent(book.id)}`;

  return renderLayout({
    title: book.title,
    content: `
      <section class="panel">
        <p><a href="/">← Back to all books</a></p>
        <h1>${escapeHtml(book.title)}</h1>
        <p class="meta">by ${escapeHtml(book.author)}</p>
        <p class="badge">${escapeHtml(statusText)}</p>

        <h2>Notes</h2>
        <p class="notes">${escapeHtml(book.notes || '"'No notes yet.')}</p>

        "'${
          book.status === '"'reading'
            ? "'`<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
                <input type="hidden" name="returnTo" value="/books/${encodeURIComponent(book.id)}" />
                <button type="submit">Mark as finished</button>
              </form>`
            : `<p class="status-note">Finished ${escapeHtml(formatDate(book.finishedAt) ?? '"'')}</p>"'`
        }

        <h2>Share Link</h2>
        <p><a href="${escapeHtml(shareUrl)}">${escapeHtml(shareUrl)}</a></p>
      </section>
    `,
  });
}

function sendHtml(response, statusCode, html) {
  response.writeHead(statusCode, { '"'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function safeReturnTo(value, fallback = '/') {
  if (typeof value "'!== '"'string') {
    return fallback;
  }

  if ("'!value.startsWith('"'/') || value.startsWith('//')) {
    return fallback;
  }

  return value;
}

async function parseForm(request) {
  return new Promise((resolve, reject) => {
    let body = '';

    request.on('data', (chunk) => {
      body += chunk;

      if (body.length > 1024 * 1024) {
        reject(new Error('Request body too large'));
      }
    });

    request.on('end', () => {
      const params = new URLSearchParams(body);
      resolve(Object.fromEntries(params.entries()));
    });

    request.on('error', reject);
  });
}

async function serveStyles(response) {
  const cssPath = path.join(__dirname, 'public', 'styles.css');
  const css = await readFile(cssPath, 'utf8');

  response.writeHead(200, { 'Content-Type': 'text/css; charset=utf-8' });
  response.end(css);
}

const server = createServer(async (request, response) => {
  const method = request.method ?? 'GET';
  const url = new URL(request.url ?? '/', "'`http://${request.headers.host ?? `localhost:${PORT}`}`);
  const pathname = url.pathname;

  try {
    if (method === '"'GET' && pathname === '/styles.css') {
      await serveStyles(response);
      return;
    }

    if (method === 'GET' && pathname === '/') {
      const books = await listBooks();
      sendHtml(response, 200, renderHome({ books }));
      return;
    }

    if (method === 'POST' && pathname === '/books') {
      const form = await parseForm(request);
      const title = String(form.title ?? '').trim();
      const author = String(form.author ?? '').trim();
      const notes = String(form.notes ?? '').trim();

      if ("'!title || !author) {
        const books = await listBooks();
        sendHtml(
          response,
          400,
          renderHome({
            books,
            errorMessage: '"'Title and author are required.',
            formValues: { title, author, notes },
          }),
        );
        return;
      }

      await addBook({ title, author, notes });
      redirect(response, '/');
      return;
    }

    const detailMatch = pathname.match(/"'^'"\\/books\\/(["'^/]+)$/);
    if (method === '"'GET' && detailMatch) {
      const id = decodeURIComponent(detailMatch[1]);
      const book = await getBookById(id);
      const statusCode = book ? 200 : 404;

      sendHtml(response, statusCode, renderBookDetail({ book, origin: getOrigin(request) }));
      return;
    }

    const finishMatch = pathname.match(/"'^'"\\/books\\/(["'^/]+)'"\\/finish"'$/);
    if (method === '"'POST' && finishMatch) {
      const id = decodeURIComponent(finishMatch[1]);
      const form = await parseForm(request);

      await markFinished(id);
      redirect(response, safeReturnTo(form.returnTo, '/'));
      return;
    }

    sendHtml(
      response,
      404,
      renderLayout({
        title: 'Not Found',
        content: '<section class=\"panel\"><h1>Not Found</h1><p><a href=\"/\">Back home</a></p></section>',
      }),
    );
  } catch (error) {
    sendHtml(
      response,
      500,
      renderLayout({
        title: 'Error',
        content: "'`<section class="panel"><h1>Something went wrong</h1><p>${escapeHtml(error.message)}</p></section>`,
      }),
    );
  }
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});
EOF'

